def apply(tpl: str) -> tuple[str, list[str]]:
    """Ersetzt alle Paare; gibt den englischen Quelltext und die nicht gefundenen deutschen Texte zurück."""
    missing = []
    for de, en in PAIRS:
        if de in tpl:
            tpl = tpl.replace(de, en)
        else:
            missing.append(de[:70])
    return tpl, missing
